const { SignedXml } = require('xml-crypto');
const { DOMParser } = require('xmldom');

function verifyAssertion(assertionXml, idpPublicCertPem) {
  const doc = new DOMParser().parseFromString(assertionXml);
  const signatureNode = doc.getElementsByTagName('ds:Signature')[0];

  const sig = new SignedXml({
    publicCert: idpPublicCertPem,
  });
  sig.loadSignature(signatureNode);

  const isValid = sig.checkSignature(assertionXml);
  if (!isValid) {
    throw new Error('assertion signature does not match, reject login');
  }

  const subject = doc.getElementsByTagName('saml:NameID')[0].textContent;
  return { verified: true, email: subject };
}

